CREATE OR REPLACE FUNCTION update_customer_order_count()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE customers SET order_count = order_count + 1 WHERE id = NEW.customer_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE customers SET order_count = order_count - 1 WHERE id = OLD.customer_id;
    END IF;
    RETURN NULL;
END;
$$;

CREATE TRIGGER trg_order_insert AFTER INSERT ON orders FOR EACH ROW EXECUTE FUNCTION update_customer_order_count();
CREATE TRIGGER trg_order_delete AFTER DELETE ON orders FOR EACH ROW EXECUTE FUNCTION update_customer_order_count();
